<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class mbuyer extends CI_Controller {    public function __construct() {        parent::__construct();        //error_reporting(0);        $this->load->model(CNFCOMPANY."mbuyermodel");        $this->load->helper('xssclean');        $this->limit = LIMITPERPAGE;        fnIfCheckUserLoggedIn();    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarHashId		    									= $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if($VarHashId <>'' && base64_decode(urldecode($VarHashId))) {            $VarId                                              = base64_decode(urldecode($VarHashId));            $ArrResults = $this->mbuyermodel->fnGetInfo('', '', $VarId);            $ArrData['buyer']                                        = $ArrResults;            $ArrData['VarId']					                = $ArrResults[0]->id;        } else {        }        $this->load->view(CNFCOMPANY.'addeditbuyer',$ArrData);    }    public function updateBuyerInfo() {        $VarUserInfo = fnGetUserLoggedInfo(1);        if(isset($VarUserInfo['companyid'])) {            $VarCompanyId = $VarUserInfo['companyid'];        }        $ArrResult                                              = array();        $VarBuyer				    					        = xssclean($this->input->post('by'));        $VarStatus												= xssclean($this->input->post('s'));        $VarId       											= xssclean($this->input->post('id'));        $VarUpdatedBy											= fnGetUserLoggedInfo();        if($VarBuyer<>'') {            $ArrBuyerData                                      = array('id'=>$VarId,'buyername'=>$VarBuyer,'companyid'=>$VarCompanyId,                'status' => $VarStatus, 'updatedby' => $VarUpdatedBy, 'dateupdated' => date('Y-m-d H:i:s'));            if (empty($VarId)) {                $ArrBuyerData['datecreated']                   = date('Y-m-d H:i:s');            }            $ArrResult = $this->mbuyermodel->saveInfo($ArrBuyerData);            echo json_encode($ArrResult);            die;        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg']								    = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function manage() {        $VarFrom												= xssclean($this->input->post('rfrom'));        $VarBuyer										        = xssclean($this->input->post('buyer'));        $VarStatus										        = xssclean($this->input->post('s'));        $clickedColumnId  										= xssclean($this->input->post('columnId'));        $newsortorder  										    = xssclean($this->input->post('sortorder'));        $VarAfilter  										    = xssclean($this->input->post('afilter'));        $ArrDbCols = array('buyername', 'contactname', 'status', 'b.dateupdated');        if($VarFrom==1) {            $VarURLSegment										= 4;            $this->load->library('pagination');            $config['base_url']									= base_url().CNFCOMPANY.'mbuyer/manage/';            $config['total_rows'] = $this->mbuyermodel->fnCount($VarBuyer, $VarStatus, $VarAfilter);            $config['per_page'] = $this->limit;            $config['uri_segment']								= $VarURLSegment;            $offset												= $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby												= "dateupdated";            $sortorder											= "desc";            if($clickedColumnId <> '' && $newsortorder <> '') {                if(array_key_exists($clickedColumnId,$ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrList = $this->mbuyermodel->fnList($VarBuyer, $VarStatus, $this->limit, $offset, $sortby, $sortorder, $VarAfilter)->result();            $data['pagination']									= $this->pagination->create_linkswithajax('Buyers');            $i=0;            $ArrFnlList										    = array();            $ArrStatus                                          = unserialize(ARRSTATUS);            foreach ($ArrList as $ObjUnit) {                $ArrFnlList[$i]['id']						    = $ObjUnit->id;                $ArrFnlList[$i]['buyer']						= $ObjUnit->buyername;                $ArrFnlList[$i]['ub'] = $ObjUnit->contactname;                $ArrFnlList[$i]['s']						    = $ArrStatus[$ObjUnit->status];                $ArrFnlList[$i]['du'] = $ObjUnit->formattedDateUpdated;                $i=$i+1;            }            echo json_encode(array('errcode'=>1,'cn'=>$config['total_rows'],'ct'=>$i,'re'=>$ArrFnlList,'pa'=>base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY.'managebuyer');        }    }    function changemStatus() {        $VarActDeactOption										= xssclean($this->input->post('actdeactFabType'));        $VarCid 	   										    = xssclean($this->input->post('cid'));        if($VarActDeactOption <> '' && $VarCid <> '') {            $this->mbuyermodel->fnChangeComStat($VarCid,$VarActDeactOption);        }        echo json_encode(array('errcode'=> 1));        die;    }    function delBuyerInfo() {        $VarBuyerId                                             = xssclean($this->input->post('id'));        $VarUpdatedBy                                         = fnGetUserLoggedInfo();        if($VarBuyerId>=1) {            $ArrResult             					          = $this->mbuyermodel->fnDelBuyer($VarBuyerId,$VarUpdatedBy);        } else {            $ArrResult['errcode']						      = -1;            $ArrResult['msg']							      = '';        }        echo json_encode($ArrResult);    }}